package com.tekwatt.payment.entity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;@Entity @Table(name="scan_pay_orders")public class ScanPayOrder{@Id private UUID id;@Column(nullable=false,unique=true,length=40)private String orderNumber;@Column(nullable=false)private UUID tenantId;@Column(nullable=false)private UUID userId;private UUID stationId;private UUID chargerId;@Column(nullable=false,precision=12,scale=2)private BigDecimal amount;@Column(nullable=false,length=3)private String currency;@Column(nullable=false,length=20)private String status;private UUID paymentId;private UUID sessionId;@Column(nullable=false,length=1000)private String payload;@Column(nullable=false,updatable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;protected ScanPayOrder(){}public ScanPayOrder(UUID t,UUID u,UUID s,UUID c,BigDecimal a,String cur,String p){id=UUID.randomUUID();orderNumber="SP-"+Instant.now().toEpochMilli();tenantId=t;userId=u;stationId=s;chargerId=c;amount=a;currency=cur;payload=p;status="PENDING";createdAt=Instant.now();updatedAt=createdAt;}public void link(UUID payment,UUID session,String s){paymentId=payment;sessionId=session;status=s;updatedAt=Instant.now();}public UUID getId(){return id;}public String getOrderNumber(){return orderNumber;}public UUID getTenantId(){return tenantId;}public UUID getUserId(){return userId;}public UUID getStationId(){return stationId;}public UUID getChargerId(){return chargerId;}public BigDecimal getAmount(){return amount;}public String getCurrency(){return currency;}public String getStatus(){return status;}public UUID getPaymentId(){return paymentId;}public UUID getSessionId(){return sessionId;}public String getPayload(){return payload;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
